/**
 * Probe module: mimics the shape C will publish in shared/formula.js.
 * @param {Iterable<readonly [number, number, string]>} cells
 * @returns {Map<string, string>}
 */
export function evaluate(cells) {
  const out = new Map();
  for (const [row, col, raw] of cells) out.set(`${row}:${col}`, raw);
  return out;
}

/**
 * @param {string} formula
 * @param {number} dRow
 * @param {number} dCol
 * @param {{rowCount: number, colCount: number}} bounds
 * @returns {string}
 */
export function rewriteRefsOnCopy(formula, dRow, dCol, bounds) {
  return `${formula}|${dRow}|${dCol}|${bounds.rowCount}x${bounds.colCount}`;
}

export const PROBE_MARKER = 'F26_SHARED_RUNTIME_PROBE_MARKER';
EOF
